<template>
  <section ref="root" class="story-editor" :class="[{ 'story-editor--fullscreen': fullscreen }, `story-editor--${document.settings.theme}`, `story-editor--${document.settings.density}`]">
    <header class="story-editor__header">
      <div><strong>{{ document.title }}</strong><small>{{ document.messages.length }} 条消息 · {{ document.characters.length - 1 }} 个角色</small></div>
      <div class="story-editor__header-actions"><button @click="$emit('download')">下载 SSP</button><button v-if="!document.settings.previewOnly" @click="moveMode=!moveMode">{{ moveMode ? '完成移动' : '移动' }}</button><button @click="$emit('preview')">沉浸预览</button><button @click="toggleFullscreen">{{ fullscreen ? '退出全屏' : '全屏' }}</button></div>
    </header>
    <div class="story-editor__size"><span>画布宽度</span><input v-model.number="width" type="range" min="360" max="1200" step="20" /></div>
    <main ref="messageList" :style="canvasStyle" @click="actionMenuId=''">
      <div v-if="!document.messages.length" class="empty">还没有消息。请从下方选择角色并开始写作。</div>
      <template v-for="(message,index) in document.messages" :key="message.id">
      <article v-if="desktopInsert && insertTarget===message.id && insertDirection==='above'" class="story-message story-message--inline-insert" :class="`story-message--${selectedCharacter()?.position || 'left'}`" @click.stop><span v-if="insertAvatarSlot()" class="avatar-slot"><button class="avatar"><img v-if="avatar(selectedCharacter())" :src="avatar(selectedCharacter())" alt="" /><span v-else>{{ selectedCharacter()?.name?.slice(0,1) || '旁' }}</span></button></span><div class="story-message__content"><small v-if="document.settings.showNames">{{ selectedCharacter()?.name }}</small><div class="bubble" :class="{ 'bubble--narrator-avatar': insertNarratorAvatar() }"><button v-if="insertNarratorAvatar()" class="narrator-avatar" @click.stop="selectedCharacterId && selectCharacter(selectedCharacterId)"><img v-if="avatar(selectedCharacter())" :src="avatar(selectedCharacter())" alt="" /><span v-else>{{ selectedCharacter()?.name?.slice(0,1) || '旁' }}</span></button><textarea ref="insertArea" v-model="insertDraft" rows="2" placeholder="插入一条消息" @keydown.enter.exact.prevent="addInsertedMessages" @keydown.esc.prevent="cancelInsert" /></div></div><div class="inline-insert-actions"><button title="添加图片" @click="imageInput?.click()">图</button><button class="primary" :disabled="!insertDraft.trim()" @click="addInsertedMessages">✓</button><button @click="cancelInsert">✕</button></div></article>
      <article :data-id="message.id" class="story-message" :class="[`story-message--${character(message.characterId)?.position || 'left'}`, `story-message--group-${groupPosition(index)}`, { 'story-message--selected': selected.has(message.id), 'story-message--menu-open': actionMenuId===message.id } ]" @click="selectMessage(message.id)">
        <button v-if="moveMode" class="drag" title="拖动消息">⠿</button>
        <span v-if="avatarSlot(index)" class="avatar-slot" :class="{ 'avatar-slot--bottom': document.settings.avatarAlignment==='bottom' }"><button v-if="showAvatar(index)" class="avatar" @click.stop="selectCharacter(message.characterId)"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><span v-else>{{ character(message.characterId)?.name?.slice(0,1) || '旁' }}</span></button></span>
        <div class="story-message__content">
          <small v-if="(document.settings.showNames && groupStarts(index)) || document.settings.showTime"><template v-if="document.settings.showNames && groupStarts(index)">{{ character(message.characterId)?.name }}<template v-if="document.settings.showQqInEditor && character(message.characterId)?.imUserId"> · {{ character(message.characterId)?.imUserId }}</template></template><template v-if="document.settings.showTime">{{ document.settings.showNames && groupStarts(index) ? ' · ' : '' }}{{ messageTime(message) }}</template></small>
          <div class="bubble" :class="{ 'bubble--narrator-avatar': showNarratorBubbleAvatar(index) }" :style="editingId===message.id && !mobileEditing && editingBubbleWidth ? {width:`${editingBubbleWidth}px`,maxWidth:'100%',boxSizing:'border-box'} : undefined">
            <button v-if="showNarratorBubbleAvatar(index)" class="narrator-avatar" @click.stop="selectCharacter(message.characterId)"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><span v-else>{{ character(message.characterId)?.name?.slice(0,1) || '旁' }}</span></button>
            <img v-if="message.kind==='image'" :src="asset(message.asset)" :alt="message.alt || '图片'" />
            <textarea v-else-if="editingId===message.id && !mobileEditing" ref="editArea" v-model="editText" rows="1" @input="resizeTextArea" @keydown.enter.exact.prevent="commitEdit(message.id)" @keydown.esc.prevent="cancelEdit" />
            <span v-else>{{ displayText(message.text) }}</span>
          </div>
        </div>
        <div v-if="!document.settings.previewOnly" class="message-actions" :class="{ 'message-actions--open': actionMenuId===message.id }">
          <button class="message-edit" title="消息操作" aria-label="消息操作" @click.stop="actionMenuId=actionMenuId===message.id?'':message.id">✎</button>
          <div v-if="actionMenuId===message.id" class="message-menu" role="menu" aria-label="消息操作"><button role="menuitem" class="danger" @click.stop="actionMenuId='';removeSelected(message.id)"><b>⌫</b>删除</button><button v-if="message.kind==='text'" role="menuitem" @click.stop="startEdit(message)"><b>✎</b>编辑</button><button role="menuitem" @click.stop="openInsert(message.id,'above');actionMenuId=''"><b>↑</b>上插</button><button role="menuitem" @click.stop="openInsert(message.id,'below');actionMenuId=''"><b>↓</b>下插</button></div>
        </div>
      </article>
      <article v-if="desktopInsert && insertTarget===message.id && insertDirection==='below'" class="story-message story-message--inline-insert" :class="`story-message--${selectedCharacter()?.position || 'left'}`" @click.stop><span v-if="insertAvatarSlot()" class="avatar-slot"><button class="avatar"><img v-if="avatar(selectedCharacter())" :src="avatar(selectedCharacter())" alt="" /><span v-else>{{ selectedCharacter()?.name?.slice(0,1) || '旁' }}</span></button></span><div class="story-message__content"><small v-if="document.settings.showNames">{{ selectedCharacter()?.name }}</small><div class="bubble" :class="{ 'bubble--narrator-avatar': insertNarratorAvatar() }"><button v-if="insertNarratorAvatar()" class="narrator-avatar" @click.stop="selectedCharacterId && selectCharacter(selectedCharacterId)"><img v-if="avatar(selectedCharacter())" :src="avatar(selectedCharacter())" alt="" /><span v-else>{{ selectedCharacter()?.name?.slice(0,1) || '旁' }}</span></button><textarea ref="insertArea" v-model="insertDraft" rows="2" placeholder="插入一条消息" @keydown.enter.exact.prevent="addInsertedMessages" @keydown.esc.prevent="cancelInsert" /></div></div><div class="inline-insert-actions"><button title="添加图片" @click="imageInput?.click()">图</button><button class="primary" :disabled="!insertDraft.trim()" @click="addInsertedMessages">✓</button><button @click="cancelInsert">✕</button></div></article>
      </template>
    </main>

    <section v-if="!document.settings.previewOnly" class="composer">
      <textarea v-model="draft" rows="2" placeholder="每行一条消息；按 Ctrl+Enter 发送" @keydown.ctrl.enter.prevent="addMessages" />
      <div><button @click="imageInput?.click()">图片</button><button class="primary" :disabled="!draft.trim()" @click="addMessages">发送</button></div>
      <input ref="imageInput" hidden type="file" accept="image/*" @change="addImage" />
    </section>

    <nav v-if="!document.settings.previewOnly" class="characters" aria-label="角色选择">
      <button v-for="item in document.characters" :key="item.id" :class="{active:selectedCharacterId===item.id}" @click="characterClick(item)">
        <span class="character-avatar"><img v-if="avatar(item)" :src="avatar(item)" alt="" /><i v-else>{{ item.name.slice(0,1) }}</i></span><small>{{ item.name }}</small><em>{{ positionText(item) }}</em>
      </button>
      <button class="character-add" @click="newCharacter">＋<small>新增角色</small></button>
    </nav>

    <Teleport to="body"><div v-if="editingCharacter" class="character-modal" @click.self="editingCharacter=null"><form @submit.prevent="saveCharacter"><h3>编辑角色</h3><label>角色名<input v-model="characterForm.name" maxlength="80" required /></label><label>QQ 号<input v-model="characterForm.imUserId" inputmode="numeric" /></label><label>位置<select v-model="characterForm.placement"><option v-if="!editingCharacter.isNarrator" value="left">左侧</option><option v-if="!editingCharacter.isNarrator" value="right">右侧</option><option value="narrator">旁白（无头像）</option><option value="narrator-avatar">旁白（有头像）</option></select></label><label>头像<input type="file" accept="image/*" @change="setAvatar" /></label><div class="avatar-preview"><img v-if="characterForm.avatarUrl" :src="characterForm.avatarUrl" alt="头像预览" /><span v-else>输入 QQ 号后会自动获取头像</span></div><footer><button type="button" @click="editingCharacter=null">取消</button><button v-if="!editingCharacter.isNarrator" type="button" class="danger" @click="deleteCharacter">删除角色</button><button class="primary" type="submit">保存</button></footer></form></div></Teleport>
    <Teleport to="body"><div v-if="editingId && mobileEditing" class="message-edit-backdrop" @click.self="cancelEdit"><section class="message-edit-sheet"><header><strong>修改</strong><button aria-label="关闭编辑" @click="cancelEdit">✕</button></header><div class="message-edit-row"><textarea ref="editArea" v-model="editText" rows="2" @keydown.ctrl.enter.prevent="commitEdit(editingId)" /><button class="primary" :disabled="!editText.trim()" @click="commitEdit(editingId)">✓</button></div><nav aria-label="选择消息角色"><button v-for="item in document.characters" :key="item.id" :class="{active:editCharacterId===item.id}" @click="editCharacterId=item.id"><span class="character-avatar"><img v-if="avatar(item)" :src="avatar(item)" alt="" /><i v-else>{{ item.name.slice(0,1) }}</i></span><small>{{ item.name }}</small></button></nav></section></div></Teleport>
    <Teleport to="body"><div v-if="mobileInsert" class="message-edit-backdrop" @click.self="cancelInsert"><section class="message-edit-sheet"><header><strong>{{ insertDirection==='above'?'上插':'下插' }}</strong><button aria-label="关闭插入" @click="cancelInsert">✕</button></header><div class="message-edit-row"><textarea ref="insertArea" v-model="insertDraft" rows="2" placeholder="请输入消息" @keydown.ctrl.enter.prevent="addInsertedMessages" /><button @click="imageInput?.click()">图</button><button class="primary" :disabled="!insertDraft.trim()" @click="addInsertedMessages">✓</button></div><nav aria-label="选择消息角色"><button v-for="item in document.characters" :key="item.id" :class="{active:selectedCharacterId===item.id}" @click="selectedCharacterId=item.id"><span class="character-avatar"><img v-if="avatar(item)" :src="avatar(item)" alt="" /><i v-else>{{ item.name.slice(0,1) }}</i></span><small>{{ item.name }}</small></button></nav></section></div></Teleport>
  </section>
</template>

<script setup lang="ts">
import Sortable from "sortablejs";
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, toRaw, watch } from "vue";
import { createStoryId, storyDisplayText, storyMessageGroupPosition } from "~/story/model";
import type { StoryArchive, StoryCharacter, StoryMessage, StoryPosition } from "~/story/types";
const props=defineProps<{archive:StoryArchive;assetUrl:(id:string)=>string}>();const emit=defineEmits<{change:[StoryArchive];download:[];preview:[]}>();
type StoryPlacement=StoryPosition|'narrator-avatar';
const document=computed(()=>props.archive.document);const root=ref<HTMLElement>();const messageList=ref<HTMLElement>();const imageInput=ref<HTMLInputElement>();const editArea=ref<HTMLTextAreaElement[]>();const insertArea=ref<HTMLTextAreaElement[]>();const fullscreen=ref(false);const moveMode=ref(false);const width=ref(document.value.settings.canvasWidth);const selected=reactive(new Set<string>());const selectedCharacterId=ref(document.value.characters.find(c=>!c.isNarrator)?.id||'character-narrator');const editingId=ref('');const editText=ref('');const editCharacterId=ref('');const editingBubbleWidth=ref(0);const mobileEditing=ref(false);const actionMenuId=ref('');const draft=ref('');const insertDraft=ref('');const insertTarget=ref('');const insertDirection=ref<'above'|'below'>('below');const desktopInsert=ref(false);const mobileInsert=ref(false);const editingCharacter=ref<StoryCharacter|null>(null);const characterForm=reactive({name:'',imUserId:'',placement:'left' as StoryPlacement,avatarUrl:'',localAssetId:''});let sortable:Sortable|null=null;
const canvasStyle=computed(()=>({'--canvas-width':`${width.value}px`,'--bubble-width':`${document.value.settings.bubbleMaxWidth}%`,'--font-size':`${document.value.settings.fontSize}px`,'--avatar-size':`${document.value.settings.avatarSize}px`,'--narrator-avatar-size':`${Math.max(20,Math.round(document.value.settings.avatarSize*.68))}px`}));
function cloneArchive():StoryArchive{return{document:structuredClone(toRaw(document.value)),assets:new Map(toRaw(props.archive.assets))}}function update(mutator:(archive:StoryArchive)=>void){const archive=cloneArchive();mutator(archive);archive.document.updatedAt=new Date().toISOString();emit('change',archive)}
function character(id:string){return document.value.characters.find(c=>c.id===id)}function asset(value?:{id:string;sourceUrl?:string}){return value?(props.archive.assets.has(value.id)?props.assetUrl(value.id):value.sourceUrl||value.id):''}function avatar(c?:StoryCharacter){return asset(c?.avatar)||(c?.imUserId?`/api/editor/avatar/qq/${encodeURIComponent(c.imUserId)}`:'')}function positionText(c:StoryCharacter){return c.position==='right'?'右':c.position==='narrator'?(c.narratorAvatar?'旁白头像':'旁白'):'左'}
function groupPosition(index:number){return storyMessageGroupPosition(document.value,index)}
function groupStarts(index:number){const position=groupPosition(index);return position==='single'||position==='first'}
function avatarSlot(index:number){const c=character(document.value.messages[index].characterId);return document.value.settings.showAvatars&&c?.position!=='narrator'}
function showAvatar(index:number){if(!avatarSlot(index))return false;const position=groupPosition(index);return document.value.settings.avatarAlignment==='bottom'?(position==='single'||position==='last'):(position==='single'||position==='first')}
function showNarratorBubbleAvatar(index:number){const c=character(document.value.messages[index].characterId);return !!(document.value.settings.showAvatars&&c?.position==='narrator'&&c.narratorAvatar&&groupStarts(index))}
function displayText(text:string){return storyDisplayText(text,document.value.settings.preserveLineBreaks)}
function messageTime(message:StoryMessage){if(message.timeText)return message.timeText;if(!message.time)return '--:--';const value=message.time>10_000_000_000?message.time:message.time*1000;return new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}
function selectMessage(id:string){if(!moveMode.value)return;if(selected.has(id))selected.delete(id);else selected.add(id)}function selectCharacter(id:string){selectedCharacterId.value=id}function selectedCharacter(){return character(selectedCharacterId.value)}function insertAvatarSlot(){return document.value.settings.showAvatars&&selectedCharacter()?.position!=='narrator'}function insertNarratorAvatar(){const c=selectedCharacter();return !!(document.value.settings.showAvatars&&c?.position==='narrator'&&c.narratorAvatar)}
function startEdit(message:StoryMessage){if(message.kind!=='text')return;const selector=`[data-id="${globalThis.CSS.escape(message.id)}"] .bubble`;editingBubbleWidth.value=Math.ceil(root.value?.querySelector<HTMLElement>(selector)?.getBoundingClientRect().width||0);actionMenuId.value='';editingId.value=message.id;editText.value=displayText(message.text);editCharacterId.value=message.characterId;mobileEditing.value=globalThis.matchMedia('(max-width:650px)').matches;nextTick(()=>{const area=root.value?.querySelector<HTMLTextAreaElement>(`[data-id="${globalThis.CSS.escape(message.id)}"] textarea`);if(area){area.style.height='auto';area.style.height=`${Math.min(420,area.scrollHeight)}px`;area.focus()}else editArea.value?.[0]?.focus()})}function resizeTextArea(event:Event){const area=event.target as HTMLTextAreaElement;area.style.height='auto';area.style.height=`${Math.min(420,area.scrollHeight)}px`}function cancelEdit(){editingId.value='';editText.value='';editCharacterId.value='';editingBubbleWidth.value=0;mobileEditing.value=false}function commitEdit(id:string){const value=editText.value.trim();if(!value)return;update(a=>{const m=a.document.messages.find(v=>v.id===id);if(m?.kind==='text'){m.text=value;if(editCharacterId.value)m.characterId=editCharacterId.value}});cancelEdit()}
function openInsert(id:string,direction:'above'|'below'){insertTarget.value=id;insertDirection.value=direction;insertDraft.value='';mobileInsert.value=globalThis.matchMedia('(max-width:650px)').matches;desktopInsert.value=!mobileInsert.value;nextTick(()=>insertArea.value?.[0]?.focus())}function cancelInsert(){insertTarget.value='';insertDraft.value='';desktopInsert.value=false;mobileInsert.value=false}
function insertionIndex(messages:StoryMessage[]){if(!insertTarget.value)return messages.length;const i=messages.findIndex(m=>m.id===insertTarget.value);return Math.max(0,i+(insertDirection.value==='below'?1:0))}
function addMessages(){const lines=draft.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);if(!lines.length)return;update(a=>{const items=lines.map(text=>({id:createStoryId('message'),kind:'text' as const,characterId:selectedCharacterId.value,text,time:0,locallyInserted:true,sourceFingerprint:''}));a.document.messages.push(...items)});draft.value=''}
function addInsertedMessages(){const lines=insertDraft.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);if(!lines.length)return;update(a=>{const index=insertionIndex(a.document.messages);const items=lines.map(text=>({id:createStoryId('message'),kind:'text' as const,characterId:selectedCharacterId.value,text,time:0,locallyInserted:true,sourceFingerprint:''}));a.document.messages.splice(index,0,...items)});cancelInsert()}
async function addImage(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;const bytes=new Uint8Array(await file.arrayBuffer());const id=createStoryId('asset');update(a=>{a.assets.set(id,bytes);const index=insertionIndex(a.document.messages);a.document.messages.splice(index,0,{id:createStoryId('message'),kind:'image',characterId:selectedCharacterId.value,asset:{id,mime:file.type||'application/octet-stream',name:file.name},alt:file.name,time:0,locallyInserted:true,sourceFingerprint:''})});input.value='';cancelInsert()}
function removeSelected(id:string){const ids=selected.size&&selected.has(id)?new Set(selected):new Set([id]);if(!confirm(`确定删除 ${ids.size} 条消息吗？`))return;update(a=>a.document.messages=a.document.messages.filter(m=>!ids.has(m.id)));selected.clear()}
function characterClick(item:StoryCharacter){if(selectedCharacterId.value===item.id)openCharacter(item);else selectedCharacterId.value=item.id}function openCharacter(item:StoryCharacter){editingCharacter.value=item;const local=!!item.avatar&&props.archive.assets.has(item.avatar.id);Object.assign(characterForm,{name:item.name,imUserId:item.imUserId,placement:item.position==='narrator'&&item.narratorAvatar?'narrator-avatar':item.position,avatarUrl:local?'':item.avatar?.sourceUrl||item.avatar?.id||'',localAssetId:local?item.avatar!.id:''})}
function newCharacter(){const item:StoryCharacter={id:createStoryId('character'),name:'新角色',imUserId:'',position:'left',color:'#64748b',narratorAvatar:false,isNarrator:false,isDice:false,hidden:false};editingCharacter.value=item;Object.assign(characterForm,{name:item.name,imUserId:'',placement:'left',avatarUrl:'',localAssetId:''})}
async function setAvatar(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const id=createStoryId('asset');const bytes=new Uint8Array(await file.arrayBuffer());update(a=>a.assets.set(id,bytes));characterForm.localAssetId=id;characterForm.avatarUrl=URL.createObjectURL(file)}
function saveCharacter(){if(!editingCharacter.value)return;const id=editingCharacter.value.id;update(a=>{let target=a.document.characters.find(c=>c.id===id);if(!target){target={...editingCharacter.value!};a.document.characters.push(target)}target.name=characterForm.name.trim()||'未命名角色';target.imUserId=characterForm.imUserId.trim();target.position=target.isNarrator||characterForm.placement.startsWith('narrator')?'narrator':characterForm.placement as StoryPosition;target.narratorAvatar=characterForm.placement==='narrator-avatar';const sourceUrl=characterForm.localAssetId?'':characterForm.avatarUrl||(target.imUserId?`/api/editor/avatar/qq/${encodeURIComponent(target.imUserId)}`:'');target.avatar=characterForm.localAssetId?{id:characterForm.localAssetId,mime:'image/*',name:'头像'}:sourceUrl?{id:sourceUrl,mime:'image/*',sourceUrl,name:'头像'}:undefined;target.avatarSource=characterForm.localAssetId?'upload':target.imUserId?'qq':undefined});selectedCharacterId.value=id;editingCharacter.value=null}
function deleteCharacter(){const target=editingCharacter.value;if(!target||target.isNarrator)return;if(!confirm(`删除角色「${target.name}」及其全部消息？`))return;update(a=>{a.document.characters=a.document.characters.filter(c=>c.id!==target.id);a.document.messages=a.document.messages.filter(m=>m.characterId!==target.id)});selectedCharacterId.value='character-narrator';editingCharacter.value=null}
async function toggleFullscreen(){if(!globalThis.document.fullscreenElement)await root.value?.requestFullscreen();else await globalThis.document.exitFullscreen()}function fullscreenChanged(){fullscreen.value=!!globalThis.document.fullscreenElement}
function initSortable(){sortable?.destroy();if(!messageList.value)return;sortable=Sortable.create(messageList.value,{animation:180,handle:'.drag',disabled:!moveMode.value,onEnd:e=>{if(e.oldIndex==null||e.newIndex==null)return;const order=document.value.messages.map(m=>m.id);const dragged=order[e.oldIndex];const moving=selected.has(dragged)?order.filter(id=>selected.has(id)):[dragged];const remaining=order.filter(id=>!moving.includes(id));let anchor=e.newIndex;if(e.newIndex>e.oldIndex)anchor=Math.max(0,anchor-moving.length+1);remaining.splice(Math.min(anchor,remaining.length),0,...moving);update(a=>{const map=new Map(a.document.messages.map(m=>[m.id,m]));a.document.messages=remaining.map(id=>map.get(id)!).filter(Boolean)})}})}
watch(moveMode,()=>{if(sortable)sortable.option('disabled',!moveMode.value);if(!moveMode.value)selected.clear()});watch(width,v=>update(a=>a.document.settings.canvasWidth=v));watch(()=>props.archive.document.id,()=>{width.value=document.value.settings.canvasWidth;nextTick(initSortable)});onMounted(()=>{initSortable();globalThis.document.addEventListener('fullscreenchange',fullscreenChanged)});onBeforeUnmount(()=>{sortable?.destroy();globalThis.document.removeEventListener('fullscreenchange',fullscreenChanged)});
